// Scientific reference. Runtime claims are grounded in the linked implementation;
// experimental results retain the scope and status of their original reports.
import type { DocBlock, DocPage } from "dopedocs";

const ROOT = "https://github.com/junovhs/fractodactyl/blob/main";
const p = (text: string): DocBlock => ({ kind: "p", text });
const eq = (code: string, caption: string): DocBlock => ({ kind: "code", language: "text", code, caption });
const table = (head: [string, string], rows: [string, string][]): DocBlock => ({ kind: "table", head, rows });
const list = (...items: string[]): DocBlock => ({ kind: "list", items });
const note = (text: string): DocBlock => ({ kind: "callout", tone: "note", text });
const sources = (...paths: string[]): DocBlock => p("**Implementation and evidence:** " + paths.map(path => {
    const root = path.endsWith("/") ? ROOT.replace("/blob/", "/tree/") : ROOT;
    return `[${path}](${root}/${path})`;
}).join(" · "));

